pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.SetMinSum(100);
        c.SetLogFile(address(0));
        c.Initialized();

        // User A sends 1 wei via Put(0)
        address userA = address(0xABCD);
        vm.deal(userA, 1 ether);
        vm.prank(userA);
        c.Put{value: 1}(0);

        // Try Collect(1) from userA - should revert in reference but succeed in bug
        vm.prank(userA);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1));

        // In reference: MinSum is 100, so Collect reverts => ok == false
        // In bug: MinSum is 0, so Collect succeeds => ok == true
        assertTrue(ok == false);
    }
