pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set minimum sum to 1 wei so that 1 wei balance suffices for collect
        c.SetMinSum(1);
        // Set a dummy log file address (non-zero) – this will NOT work in the mutant
        address dummyLog = address(0x1234);
        c.SetLogFile(dummyLog);
        // Finalize initialization
        c.Initialized();
        // Give some ether to the contract for later Collect (but Collect sends from contract to user, so we need the contract balance)
        // Actually Collect sends ether to msg.sender, so we need the contract to have ether.
        // Put adds ether from user to the contract, so we first fund the user.
        address user = address(0xABCD);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 1}(0); // lockTime = 0, balance becomes 1 wei
        // Warp past unlockTime (block.timestamp + 0 is already past? Actually unlockTime = block.timestamp + 0 = block.timestamp, so need > that)
        vm.warp(block.timestamp + 1);
        // Collect 1 wei
        vm.prank(user);
        bool ok;
        try c.Collect(1) { ok = true; } catch { ok = false; }
        // Now observe Log: reference contract called LogFile.AddMessage so Log is dummyLog; mutant did nothing so Log stays address(0)
        assertTrue(c.Log() != address(0));
    }
}

