        // Set the log file address
        c.SetLogFile(logAddr);
        c.Initialized();

        // Set minimum sum to 0.5 ether
        c.SetMinSum(0.5 ether);

        // Set up actor with ether
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);

        // Put 0.6 ether with lock time 0 (so it's immediately collectable)
        vm.prank(alice);
        c.Put{value: 0.6 ether}(0);

        // Advance time past unlock (block.timestamp >= unlockTime which is block.timestamp+0 = block.timestamp)
        vm.warp(block.timestamp + 1);

        // Now try to read Log.History.length via low-level call; if Log is address(0) it reverts
        (bool success, ) = address(c.Log()).staticcall(abi.encodeWithSignature("History(uint256)", 0));

        // Before Collect, Log should be set in reference but not in bug
        // After Collect, the reference adds a message (so History has length >0), the bug doesn't
        // But we can test: call Collect then check if Log call works
        vm.prank(alice);
        c.Collect(0.6 ether);

        // Now check Log - if Log is zero address, call reverts; if not, call succeeds
        (bool successAfter, ) = address(c.Log()).staticcall(abi.encodeWithSignature("History(uint256)", 0));

        assertTrue(successAfter, "Log should be set and callable after Collect");
    }
}

