import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a LogFile contract to be passed to SetLogFile
        LogFile log = new LogFile();
        // SetMinSum to 0 so any positive balance meets the minimum
        c.SetMinSum(0);
        // Set the log file (reference sets it, mutant does nothing)
        c.SetLogFile(address(log));
        // Initialize the contract
        c.Initialized();
        // Warp time to a future timestamp so unlock condition passes
        vm.warp(1000);
        // Actor puts 1 wei with lock time 0, unlocking instantly
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 wei}(0);
        // Now Collect with amount 1
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, Log is non-zero, so AddMessage was called and no revert.
        // In the mutant, Log stays address(0), so calling LogFile.AddMessage inside Collect reverts.
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

