        vm.prank(address(this)); // caller for SetMinSum, SetLogFile, Initialized
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Send 1 wei via Put(0) - reference succeeds, buggy reverts
        address user = address(0x1234);
        vm.deal(user, 1 wei);
        vm.prank(user);
        (bool successPut, ) = address(c).call{value: 1 wei}(abi.encodeWithSignature("Put(uint256)", 0));
        // reference: successPut = true, buggy: successPut = false

        // Warp past unlockTime (unlockTime = block.timestamp + 0, so any warp makes it past)
        vm.warp(block.timestamp + 1);

        // Attempt Collect(1 wei)
        vm.prank(user);
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 wei));
        // reference: successCollect = true (balance >= MinSum && balance >= 1 && time > unlockTime)
        // buggy: successCollect = false (balance still 0 because Put reverted)

        // The divergence: address(c).balance differs
        uint256 contractBalance = address(c).balance;
        // reference: 0 (ether transferred out via Collect)
        // buggy: 1 wei (ether stuck because Put reverted)
        assertTrue(contractBalance == 0 || contractBalance == 1 wei);
        // Actually assert exact: reference has 0, buggy has 1 wei
        assertTrue(contractBalance == 0, "Reference should have balance 0");
    }
